function AppV2(){const[user,setUser]=useState(null);const[checking,setChecking]=useState(true);useEffect(()=>{api.get("/api/auth/me").then(response=>{setUser(response.data.user);api.defaults.headers.common["X-CSRF-Token"]=response.data.user.csrf_token}).catch(()=>{}).finally(()=>setChecking(false))},[]);const onAuth=userData=>{setUser(userData);api.defaults.headers.common["X-CSRF-Token"]=userData.csrf_token};const logout=async()=>{try{await api.post("/api/auth/logout")}finally{delete api.defaults.headers.common["X-CSRF-Token"];setUser(null)}};if(checking)return <div className="auth-loading">Checking secure session…</div>;const workspace=<Protected user={user}><Shell user={user} onLogout={logout}/></Protected>;return <Routes><Route path="/" element={<Landing/>}/><Route path="/login" element={user?<Navigate to="/dashboard" replace/>:<AuthPage mode="login" onAuth={onAuth}/>}/><Route path="/register" element={user?<Navigate to="/dashboard" replace/>:<AuthPage mode="register" onAuth={onAuth}/>}/><Route path="/dashboard" element={workspace}/><Route path="/alerts" element={workspace}/><Route path="/transactions" element={workspace}/><Route path="/network" element={workspace}/><Route path="/trace" element={workspace}/><Route path="/investigations" element={workspace}/><Route path="/integrations" element={workspace}/><Route path="*" element={<Navigate to="/" replace/>}/></Routes>}
